wb_o=openpyxl.load_workbook(out)
diffs=[]
for ws_i, ws_o in zip(wb_i.worksheets, wb_o.worksheets):
    for row_i,row_o in zip(ws_i.iter_rows(), ws_o.iter_rows()):
        for ci,co in zip(row_i,row_o):
            attrs=[]
            for attr in ['font','fill','border','number_format','alignment','protection']:
                vi=getattr(ci,attr); vo=getattr(co,attr)
                # compare basic
                if attr=='font':
                    if (vi.name, vi.size, vi.bold, vi.italic, vi.color.rgb if vi.color else None, vi.color.theme if vi.color else None) != (vo.name, vo.size, vo.bold, vo.italic, vo.color.rgb if vo.color else None, vo.color.theme if vo.color else None):
                        attrs.append(attr)
                elif attr=='fill':
                    if (vi.fgColor.rgb, vi.fgColor.theme, vi.patternType) != (vo.fgColor.rgb, vo.fgColor.theme, vo.patternType):
                        attrs.append(attr)
                elif attr=='border':
                    pass
                else:
                    if getattr(vi, attr) != getattr(vo, attr):
                        attrs.append(attr)
            if attrs:
                diffs.append((ws_i.title, ci.coordinate, attrs))
print('style diffs', len(diffs))
for d in diffs[:50]: print(d)
